import os, re
import json

d = os.path.normpath(os.environ['RLM_SESSION_DIR'])
with open(d + '/../../sessions/' + os.path.basename(d) + '.jsonl') as f:
    raw = f.read()

# Flatten conversation tree to get all messages with content
data = []
for line in raw.strip().split('\n'):
    data.append(json.loads(line))

messages = []
for entry in data:
    if entry.get('type') == 'message':
        msg_data = entry.get('message', {})
        for part in msg_data.get('content', []):
            if part.get('type') == 'text':
                messages.append({'role': 'assistant', 'text': part['text']})
    elif entry.get('type') == 'toolResult':
        msg_data = entry.get('message', {})
        for part in msg_data.get('content', []):
            if part.get('type') == 'text':
                messages.append({'role': 'toolResult', 'text': part['text']})

# Parse grids from messages
grids = {}
for msg in messages:
    text = msg['text']
    if 'input (30x30)' in text or 'input (21x21)' in text or 'input (14x14)' in text:
        grids['Test input'] = text
    if 'Demo pair' in text and 'input (30x30)' in text or 'input (21x21)' in text or 'input (14x14)' in text:
        grids['Demo pair'] = text

print("Found grids:", list(grids.keys()))

